// From the Nix AST to a TypeScript module. The shape of the output is the
// shape of the input: a Nix lambda is an arrow function, a let is a block
// of consts, an attribute set is an object literal, and laziness is spelled
// out where Nix has it implicitly, as `nix.thunk(() => ...)` around the
// expressions Nix would thunk and `nix.force(x)` where it would force.
//
// Two kinds of positions matter to the emitter. In a strict position the
// code must produce a value in weak head normal form (a function body, an
// operand, a condition). In a lazy position (an attribute value, a list
// element, a call argument, a let binding) it may produce a thunk. The
// strict() and lazy() methods are the two entry points, and the rule for
// what gets thunked is the one in Nix's Expr::maybeThunk: literals,
// variables and lambdas are never thunked, everything else is.

import type {
  AttrName,
  Binding as NixBinding,
  Expr,
  Formal,
  LambdaExpr,
  Pos,
  StringPart,
} from "../syntax/ast.ts";
import { formatPos } from "../syntax/ast.ts";
import { BUILTIN_ARITY, GLOBALS } from "./builtins-table.ts";
import { type Binding, Scope, isIdentifierName } from "./scope.ts";
import { encodeSourceMap, extractMappings, marker } from "./sourcemap.ts";

// The module-level table of attribute positions; a name no mangled Nix
// identifier can take, since a `$` only ever follows a character.
const POS_TABLE = "$pos";
const IMPORT = "import";

export interface EmitOptions {
  // The Nix file being compiled, absolute.
  readonly file: string;
  // The import specifier for the runtime, as it should appear in the module.
  readonly runtimeImport: string;
  // Produce a source map; `sourceMapUrl` is what the module points at.
  readonly sourceMap?: {
    readonly url: string;
    readonly sourceRelative: string;
  };
  // The compiled module a literal relative import names, as a specifier
  // relative to this module, or null when the import leaves the tree.
  // With it, `import ./x.nix` carries `typeof import("./x.ts")` in a
  // type, which an editor follows and the runtime strips.
  readonly importTarget?: (relativeNixPath: string) => string | null;
}

export interface Emitted {
  readonly typescript: string;
  readonly sourceMap: string | null;
}

export class CompileError extends Error {
  readonly pos: Pos;

  constructor(message: string, pos: Pos) {
    super(`${formatPos(pos)}: ${message}`);
    this.pos = pos;
  }
}

const INDENT = "  ";

// The arity of each builtin, so that `map f xs` becomes one call rather
// than two applications; a constant or a Nix-level function (derivation)
// is never called directly.
const ARITY = new Map<string, number>();
for (const [name, arity] of BUILTIN_ARITY) {
  if (arity > 0 && name !== "derivation") {
    ARITY.set(name, arity);
  }
}

export function emitModule(expr: Expr, opts: EmitOptions): string {
  return emit(expr, opts).typescript;
}

export function emit(expr: Expr, opts: EmitOptions): Emitted {
  const e = new Emitter(opts);
  const marked = e.module(expr);
  const { text, mappings } = extractMappings(marked);
  if (opts.sourceMap === undefined) {
    return { typescript: text, sourceMap: null };
  }
  const name = opts.file.slice(opts.file.lastIndexOf("/") + 1);
  return {
    typescript: `${text}//# sourceMappingURL=${opts.sourceMap.url}\n`,
    sourceMap: encodeSourceMap(
      name.replace(/\.nix$/, ".ts"),
      opts.sourceMap.sourceRelative,
      mappings,
    ),
  };
}

class Emitter {
  private readonly opts: EmitOptions;
  // Module-level declarations hoisted out of the expression: formals.
  private readonly hoisted: string[] = [];
  private formalsCount = 0;
  // The literal sites of the module with positions, in the order met.
  private readonly posSites: string[] = [];
  private usesHere = false;
  private readonly dir: string;
  private readonly base: string;

  constructor(opts: EmitOptions) {
    this.opts = opts;
    const i = opts.file.lastIndexOf("/");
    this.dir = i <= 0 ? "/" : opts.file.slice(0, i);
    this.base = opts.file.slice(i + 1);
  }

  module(expr: Expr): string {
    const scope = new Scope(null);
    const body = this.lazy(expr, scope, 0);
    const lines: string[] = [];
    lines.push(`// Generated by jinx from ${this.opts.file}. Do not edit.`);
    lines.push(
      `import * as nix from ${JSON.stringify(this.opts.runtimeImport)};`,
    );
    lines.push("");
    // The table names the file through `here`, so it comes first.
    const posTable =
      this.posSites.length === 0
        ? null
        : `const ${POS_TABLE} = nix.positions(${this.fileRef()}, [${this.posSites.join(", ")}]);`;
    if (this.usesHere) {
      lines.push("const here = nix.here(import.meta.url);");
    }
    if (posTable !== null) {
      lines.push(posTable);
    }
    for (const h of this.hoisted) {
      lines.push(h);
    }
    if (this.usesHere || this.posSites.length > 0 || this.hoisted.length > 0) {
      lines.push("");
    }
    lines.push(`export default ${body};`);
    lines.push("");
    return lines.join("\n");
  }

  // ---- positions ------------------------------------------------------------

  private where(pos: Pos): string {
    return JSON.stringify(`${this.opts.file}:${pos.line}:${pos.column}`);
  }

  private hereRef(): string {
    this.usesHere = true;
    return "here";
  }

  // ---- the two entry points -------------------------------------------------

  // A Lazy: the expression itself when Nix would not thunk it, a thunk
  // otherwise.
  lazy(e: Expr, scope: Scope, depth: number): string {
    switch (e.kind) {
      case "var":
        return this.varLazy(e.name, e.pos, scope);
      case "int":
      case "float":
        return this.strict(e, scope, depth);
      case "string":
        if (e.parts.every((p) => typeof p === "string")) {
          return this.strict(e, scope, depth);
        }
        break;
      case "path":
        if (e.parts.every((p) => typeof p === "string")) {
          return this.strict(e, scope, depth);
        }
        break;
      case "lambda":
        return this.strict(e, scope, depth);
      case "list":
        if (e.elements.length === 0) {
          return "[]";
        }
        break;
      default:
        break;
    }
    return `nix.thunk(() => ${arrowBody(this.strict(e, scope, depth))})`;
  }

  // A Value in weak head normal form, stamped with where it came from.
  strict(e: Expr, scope: Scope, depth: number): string {
    return (
      marker(e.pos.line, e.pos.column) + this.strictUnmarked(e, scope, depth)
    );
  }

  private strictUnmarked(e: Expr, scope: Scope, depth: number): string {
    switch (e.kind) {
      case "var":
        return this.varStrict(e.name, e.pos, scope);
      case "int":
        return `${e.value}n`;
      case "float":
        return floatLiteral(e.value);
      case "string":
        return this.string(e.parts, scope, depth);
      case "path":
        return this.path(e, scope, depth);
      case "list":
        return this.list(e.elements, scope, depth);
      case "attrs":
        return e.recursive
          ? this.recAttrs(e.bindings, scope, depth)
          : this.attrs(e.bindings, scope, depth);
      case "select":
        return this.select(e, scope, depth);
      case "hasattr":
        return `nix.has(${this.operand(e.subject, scope, depth)}${this.attrPathArgs(e.path, scope, depth)})`;
      case "lambda":
        return this.lambda(e, scope, depth);
      case "call":
        return this.call(e, scope, depth);
      case "let":
      case "with":
      case "assert":
        return this.iife(e, scope, depth);
      case "if":
        return `(nix.asBool(${this.operand(e.condition, scope, depth)}) ? ${this.strict(e.then, scope, depth)} : ${this.strict(e.else, scope, depth)})`;
      case "unary":
        if (e.op === "!") {
          return `!nix.asBool(${this.operand(e.operand, scope, depth)})`;
        }
        return `nix.neg(${this.operand(e.operand, scope, depth)})`;
      case "binary":
        return this.binary(e.op, e.left, e.right, scope, depth);
    }
  }

  // An operand of an operator or a subject of a selection: the runtime
  // forces it, so a variable is passed as is and anything else strictly.
  private operand(e: Expr, scope: Scope, depth: number): string {
    if (e.kind === "var") {
      const r = scope.resolve(e.name);
      if (r.kind === "with" && !this.isGlobal(e.name)) {
        return `nix.lookup(${r.scopeVar}, ${JSON.stringify(e.name)})`;
      }
      return this.varLazy(e.name, e.pos, scope);
    }
    return this.strict(e, scope, depth);
  }

  // ---- variables ------------------------------------------------------------

  private varLazy(name: string, pos: Pos, scope: Scope): string {
    const r = scope.resolve(name);
    switch (r.kind) {
      case "lexical":
        return r.binding.js;
      case "with":
        // Globals are bound in Nix's base environment, which is lexical,
        // so `with { map = 1; }; map` is still builtins.map.
        if (this.isGlobal(name)) {
          return this.global(name, pos);
        }
        // A with-bound variable is a lookup in a set that may not be
        // evaluable yet, so in a lazy position it is a thunk, as in Nix.
        return `nix.thunk(() => nix.lookup(${r.scopeVar}, ${JSON.stringify(name)}))`;
      case "global":
        return this.global(name, pos);
    }
  }

  private varStrict(name: string, pos: Pos, scope: Scope): string {
    const r = scope.resolve(name);
    switch (r.kind) {
      case "lexical":
        return r.binding.whnf ? r.binding.js : `nix.force(${r.binding.js})`;
      case "with":
        if (this.isGlobal(name)) {
          return this.global(name, pos);
        }
        return `nix.force(nix.lookup(${r.scopeVar}, ${JSON.stringify(name)}))`;
      case "global":
        return this.global(name, pos);
    }
  }

  private isGlobal(name: string): boolean {
    return (
      name === "true" ||
      name === "false" ||
      name === "null" ||
      name === "builtins" ||
      name === "__curPos" ||
      this.globalBuiltin(name) !== null
    );
  }

  // A free variable: one of Nix's globals, or `__name` for builtins.name.
  private global(name: string, pos: Pos): string {
    if (name === "true" || name === "false" || name === "null") {
      return name;
    }
    if (name === "builtins") {
      return "nix.builtins";
    }
    if (name === "__curPos") {
      return `{ file: nix.add(${this.hereRef()}, ${JSON.stringify("/" + this.base)}), line: ${pos.line}n, column: ${pos.column}n }`;
    }
    const builtin = this.globalBuiltin(name);
    if (builtin === null) {
      throw new CompileError(`undefined variable '${name}'`, pos);
    }
    return builtinRef(builtin);
  }

  // The builtins.* name a free variable denotes, or null if it is not one.
  private globalBuiltin(name: string): string | null {
    if (GLOBALS.has(name)) {
      return name;
    }
    if (name.startsWith("__") && BUILTIN_ARITY.has(name.slice(2))) {
      return name.slice(2);
    }
    return null;
  }

  // ---- literals -------------------------------------------------------------

  private string(
    parts: readonly StringPart[],
    scope: Scope,
    depth: number,
  ): string {
    if (parts.every((p) => typeof p === "string")) {
      return JSON.stringify(parts.join(""));
    }
    let out = "nix.str`";
    for (const p of parts) {
      if (typeof p === "string") {
        out += templateEscape(p);
      } else {
        out += "${" + this.operand(p, scope, depth) + "}";
      }
    }
    return out + "`";
  }

  private path(
    e: Extract<Expr, { kind: "path" }>,
    scope: Scope,
    depth: number,
  ): string {
    if (e.anchor === "search") {
      return `nix.builtins.findFile(nix.builtins.nixPath, ${JSON.stringify(e.parts.join(""))})`;
    }
    const args = e.parts.map((p) =>
      typeof p === "string" ? JSON.stringify(p) : this.operand(p, scope, depth),
    );
    const dir = e.anchor === "relative" ? this.hereRef() : '""';
    return `nix.path(${dir}, ${args.join(", ")})`;
  }

  private list(elements: readonly Expr[], scope: Scope, depth: number): string {
    if (elements.length === 0) {
      return "[]";
    }
    const items = elements.map((x) => this.lazy(x, scope, depth + 1));
    return this.bracketed("[", items, "]", depth);
  }

  // ---- attribute sets -------------------------------------------------------

  private attrs(
    bindings: readonly NixBinding[],
    scope: Scope,
    depth: number,
  ): string {
    // `inherit (e) a b;` evaluates e once; when e is not a variable it is
    // hoisted into a const, which needs a block around the literal.
    const pre: string[] = [];
    const inner = new Scope(scope);
    const props: string[] = [];
    const dynamics: string[] = [];
    const fromVars = new Map<Expr, string>();
    for (const b of bindings) {
      const value = this.bindingValue(
        b,
        inner,
        scope,
        scope,
        depth + 1,
        pre,
        fromVars,
      );
      if (b.name.kind === "dynamic") {
        dynamics.push(
          `[${this.strict(b.name.expr, scope, depth + 1)}, ${value}]`,
        );
        continue;
      }
      props.push(`${propertyKey(b.name.name)}: ${value}`);
    }
    const table = this.hoistPositions(bindings);
    let literal =
      props.length === 0 && table === null
        ? "{}"
        : this.bracketed(
            "{",
            table === null ? props : [`[nix.POS]: ${table}`, ...props],
            "}",
            depth,
          );
    if (dynamics.length > 0) {
      literal = `nix.attrsDyn(${literal}, ${this.bracketed("[", dynamics, "]", depth)})`;
    }
    if (pre.length === 0) {
      return literal;
    }
    return this.block([...pre, `return ${literal};`], depth);
  }

  // The positions of a literal's static attributes, for
  // builtins.unsafeGetAttrPos: one site in the module's table, which the
  // literal carries under nix.POS. The table is one declaration per
  // module, `$pos`, decoded a site at a time when a position is asked.
  private hoistPositions(bindings: readonly NixBinding[]): string | null {
    const entries = bindings
      .filter((b) => b.name.kind === "static")
      .map(
        (b) =>
          `[${JSON.stringify((b.name as { name: string }).name)}, ${b.name.pos.line}, ${b.name.pos.column}]`,
      );
    if (entries.length === 0) {
      return null;
    }
    this.posSites.push(`[${entries.join(", ")}]`);
    return `${POS_TABLE}[${this.posSites.length - 1}]`;
  }

  // The module's Nix file as an expression: `here` joined with the base
  // name, so a compiled tree stays relocatable.
  private fileRef(): string {
    return `${this.hereRef()} + ${JSON.stringify("/" + this.base)}`;
  }

  // The lazy value of one binding. For `inherit x` the value is the outer
  // variable; for `inherit (e) x` it is the attribute of the hoisted e.
  // `fromScope` is where the `e` of `inherit (e) x` is evaluated: the
  // inner scope in let and rec, where it may name a sibling, and the
  // outer one in a plain set. Plain `inherit x` always reads the outer
  // scope.
  private bindingValue(
    b: NixBinding,
    inner: Scope,
    outer: Scope,
    fromScope: Scope,
    depth: number,
    pre: string[],
    fromVars: Map<Expr, string>,
  ): string {
    switch (b.inherited) {
      case "no":
        return this.lazy(b.value, inner, depth);
      case "scope": {
        if (b.value.kind !== "var") {
          throw new Error("internal: inherit of a non-variable");
        }
        return this.varLazy(b.value.name, b.value.pos, outer);
      }
      case "from": {
        if (
          b.value.kind !== "select" ||
          b.value.path.length !== 1 ||
          b.value.path[0]!.kind !== "static"
        ) {
          throw new Error("internal: inherit-from of an unexpected shape");
        }
        const from = b.value.subject;
        let fromJs = fromVars.get(from);
        if (fromJs === undefined) {
          if (from.kind === "var") {
            fromJs = this.varLazy(from.name, from.pos, fromScope);
          } else {
            fromJs = inner.temp("from");
            pre.push(`const ${fromJs} = ${this.lazy(from, fromScope, depth)};`);
          }
          fromVars.set(from, fromJs);
        }
        // A thunk, as Nix makes one: the set is selected from only when
        // the attribute is forced, which is what lets `inherit (self) x`
        // appear inside the fixpoint that defines self.
        return `nix.thunk(() => nix.attr(${fromJs}, ${JSON.stringify(b.value.path[0]!.name)}))`;
      }
    }
  }

  // `rec { ... }`: every attribute becomes a const the others can see,
  // then the literal collects them. Same for let, which is rec without the
  // literal.
  private recAttrs(
    bindings: readonly NixBinding[],
    scope: Scope,
    depth: number,
  ): string {
    const inner = new Scope(scope);
    const stmts: string[] = [];
    const declared = this.declareGroup(
      bindings,
      inner,
      scope,
      depth + 1,
      stmts,
    );
    const props: string[] = [];
    const dynamics: string[] = [];
    for (const b of bindings) {
      if (b.name.kind === "dynamic") {
        // Dynamic names are evaluated in the rec scope, as Nix does.
        dynamics.push(
          `[${this.strict(b.name.expr, inner, depth + 1)}, ${this.lazy(b.value, inner, depth + 1)}]`,
        );
        continue;
      }
      const js = declared.get(b.name.name)!.js;
      props.push(
        js === b.name.name ? js : `${propertyKey(b.name.name)}: ${js}`,
      );
    }
    const table = this.hoistPositions(bindings);
    let literal =
      props.length === 0 && table === null
        ? "{}"
        : this.bracketed(
            "{",
            table === null ? props : [`[nix.POS]: ${table}`, ...props],
            "}",
            depth + 1,
          );
    if (dynamics.length > 0) {
      literal = `nix.attrsDyn(${literal}, ${this.bracketed("[", dynamics, "]", depth + 1)})`;
    }
    stmts.push(`return ${literal};`);
    return this.block(stmts, depth);
  }

  // Declare the static bindings of a let or rec as consts, in an order
  // that respects `a = b;` between siblings, and return the bindings by
  // Nix name.
  private declareGroup(
    bindings: readonly NixBinding[],
    inner: Scope,
    outer: Scope,
    depth: number,
    stmts: string[],
  ): Map<string, Binding> {
    const statics = bindings.filter((b) => b.name.kind === "static");
    const byName = new Map<string, NixBinding>();
    for (const b of statics) {
      byName.set((b.name as { name: string }).name, b);
    }
    // Declare first, so bodies can refer to any sibling.
    const declared = new Map<string, Binding>();
    for (const b of statics) {
      const name = (b.name as { name: string }).name;
      declared.set(name, inner.declare(name, this.isWhnf(b, byName, outer)));
    }
    // Emit in dependency order for direct sibling references.
    const emitted = new Set<string>();
    const visiting = new Set<string>();
    const pre: string[] = [];
    const fromVars = new Map<Expr, string>();
    const visit = (name: string): void => {
      if (emitted.has(name) || visiting.has(name)) {
        return;
      }
      visiting.add(name);
      const b = byName.get(name)!;
      if (
        b.inherited === "no" &&
        b.value.kind === "var" &&
        byName.has(b.value.name) &&
        b.value.name !== name
      ) {
        visit(b.value.name);
      }
      let value: string;
      if (
        b.inherited === "no" &&
        b.value.kind === "var" &&
        byName.has(b.value.name)
      ) {
        // A sibling reference that is part of a cycle is a reference to a
        // not-yet-declared const; a thunk defers the read.
        value = emitted.has(b.value.name)
          ? declared.get(b.value.name)!.js
          : `nix.thunk(() => ${declared.get(b.value.name)!.js})`;
      } else {
        value = this.bindingValue(b, inner, outer, inner, depth, pre, fromVars);
      }
      stmts.push(...pre.splice(0));
      stmts.push(`const ${declared.get(name)!.js} = ${value};`);
      visiting.delete(name);
      emitted.add(name);
    };
    for (const name of byName.keys()) {
      visit(name);
    }
    return declared;
  }

  // Whether a binding's const will hold a value rather than a thunk.
  private isWhnf(
    b: NixBinding,
    siblings: Map<string, NixBinding>,
    outer: Scope,
  ): boolean {
    if (b.inherited === "from") {
      return false;
    }
    const v = b.value;
    switch (v.kind) {
      case "int":
      case "float":
      case "lambda":
        return true;
      case "string":
      case "path":
        return v.parts.every((p) => typeof p === "string");
      case "list":
        return v.elements.length === 0;
      case "var": {
        if (b.inherited === "scope") {
          const r = outer.resolve(v.name);
          return r.kind === "lexical" ? r.binding.whnf : r.kind === "global";
        }
        // A sibling or outer variable: lazy unless known otherwise. Cycles
        // make this conservative rather than exact.
        if (siblings.has(v.name)) {
          return false;
        }
        const r = outer.resolve(v.name);
        return r.kind === "lexical" ? r.binding.whnf : r.kind === "global";
      }
      default:
        return false;
    }
  }

  // ---- selection ------------------------------------------------------------

  private select(
    e: Extract<Expr, { kind: "select" }>,
    scope: Scope,
    depth: number,
  ): string {
    // `builtins.x` on the global builtins is the builtin itself.
    if (
      e.subject.kind === "var" &&
      e.subject.name === "builtins" &&
      scope.resolve("builtins").kind === "global" &&
      e.fallback === undefined
    ) {
      const [first, ...rest] = e.path;
      if (
        first !== undefined &&
        first.kind === "static" &&
        BUILTIN_ARITY.has(first.name)
      ) {
        const head = builtinRef(first.name);
        return rest.length === 0
          ? head
          : `nix.sel(${head}${this.attrPathArgs(rest, scope, depth)})`;
      }
    }
    const subject = this.operand(e.subject, scope, depth);
    if (e.fallback !== undefined) {
      return `nix.selOr(${subject}, () => ${arrowBody(this.strict(e.fallback, scope, depth + 1))}${this.attrPathArgs(e.path, scope, depth)})`;
    }
    return `nix.sel(${subject}${this.attrPathArgs(e.path, scope, depth)})`;
  }

  private attrPathArgs(
    path: readonly AttrName[],
    scope: Scope,
    depth: number,
  ): string {
    return path
      .map(
        (a) =>
          ", " +
          (a.kind === "static"
            ? JSON.stringify(a.name)
            : `nix.key(${this.strict(a.expr, scope, depth + 1)})`),
      )
      .join("");
  }

  // ---- functions ------------------------------------------------------------

  private lambda(e: LambdaExpr, scope: Scope, depth: number): string {
    const inner = new Scope(scope);
    if (e.formals === undefined) {
      const param = inner.declare(e.param!, false);
      return `(${param.js}) => ${arrowBody(this.body(e.body, inner, depth))}`;
    }
    const argVar = inner.temp("args");
    const stmts: string[] = [];
    const attrsVar = inner.temp("$");
    const formalsConst = this.hoistFormals(
      e.formals.entries,
      e.formals.ellipsis,
    );
    stmts.push(`const ${attrsVar} = nix.formals(${argVar}, ${formalsConst});`);
    if (e.param !== undefined) {
      const whole = inner.declare(e.param, false);
      stmts.push(`const ${whole.js} = ${argVar};`);
    }
    // Declare every formal before emitting defaults, which may refer to
    // one another and to the @-bound argument.
    const declared = e.formals.entries.map((f) => ({
      f,
      b: inner.declare(f.name, false),
    }));
    for (const { f, b } of declared) {
      if (f.fallback === undefined) {
        stmts.push(
          `const ${b.js} = nix.arg(${attrsVar}, ${JSON.stringify(f.name)});`,
        );
      } else {
        stmts.push(
          `const ${b.js} = nix.argOr(${attrsVar}, ${JSON.stringify(f.name)}, () => ${arrowBody(this.strict(f.fallback, inner, depth + 1))});`,
        );
      }
    }
    stmts.push(...this.bodyStatements(e.body, inner, depth + 1));
    return `nix.lambda((${argVar}) => ${this.block(stmts, depth)}, ${formalsConst})`;
  }

  private hoistFormals(entries: readonly Formal[], ellipsis: boolean): string {
    const name = `formals$${++this.formalsCount}`;
    const args = entries
      .map((f) => `${propertyKey(f.name)}: ${f.fallback !== undefined}`)
      .join(", ");
    this.hoisted.push(
      `const ${name} = { args: { ${args} }, ellipsis: ${ellipsis} };`,
    );
    return name;
  }

  // A function body: a block when the body is a let/with/assert chain, so
  // its bindings read as statements; otherwise the expression.
  private body(e: Expr, scope: Scope, depth: number): string {
    if (e.kind === "let" || e.kind === "with" || e.kind === "assert") {
      return this.block(this.bodyStatements(e, scope, depth + 1), depth);
    }
    return this.strict(e, scope, depth);
  }

  // Statements ending in a return, unwrapping nested let/with/assert.
  private bodyStatements(e: Expr, scope: Scope, depth: number): string[] {
    const stmts: string[] = [];
    let cur = e;
    let s = scope;
    for (;;) {
      if (cur.kind === "let") {
        const inner = new Scope(s);
        this.declareGroup(cur.bindings, inner, s, depth, stmts);
        s = inner;
        cur = cur.body;
        continue;
      }
      if (cur.kind === "with") {
        const outerWith = s.innermostWith();
        const inner = new Scope(s, s.temp("w"));
        stmts.push(
          `const ${inner.withVar} = nix.withScope(${this.lazy(cur.scope, s, depth)}, ${outerWith ?? "null"});`,
        );
        s = inner;
        cur = cur.body;
        continue;
      }
      if (cur.kind === "assert") {
        stmts.push(
          `nix.assert_(${this.operand(cur.condition, s, depth)}, ${this.where(cur.pos)});`,
        );
        cur = cur.body;
        continue;
      }
      break;
    }
    stmts.push(`return ${this.strict(cur, s, depth)};`);
    return stmts;
  }

  private iife(e: Expr, scope: Scope, depth: number): string {
    return this.block(this.bodyStatements(e, scope, depth + 1), depth);
  }

  // ---- application ----------------------------------------------------------

  private call(
    e: Extract<Expr, { kind: "call" }>,
    scope: Scope,
    depth: number,
  ): string {
    // Flatten `f a b c`.
    const args: Expr[] = [];
    let head: Expr = e;
    while (head.kind === "call") {
      args.unshift(head.arg);
      head = head.fn;
    }
    const builtin = this.builtinHead(head, scope);
    if (builtin !== null) {
      const arity = ARITY.get(builtin);
      if (arity !== undefined && args.length >= arity) {
        const direct = args
          .slice(0, arity)
          .map((a) => this.lazy(a, scope, depth + 1));
        const callee = this.typedImport(
          builtin,
          args[0]!,
          `${builtinRef(builtin)}(${direct.join(", ")})`,
        );
        if (args.length === arity) {
          return callee;
        }
        const rest = args
          .slice(arity)
          .map((a) => this.lazy(a, scope, depth + 1));
        return `nix.app(${callee}, ${rest.join(", ")})`;
      }
    }
    const fn = this.operand(head, scope, depth);
    const rendered = args.map((a) => this.lazy(a, scope, depth + 1));
    return `nix.app(${fn}, ${rendered.join(", ")})`;
  }

  // `import ./x.nix` with a literal relative path, applied to further
  // arguments or not: the call, annotated with the module it loads so an
  // editor can follow the edge. Any other builtin call is returned as is.
  private typedImport(builtin: string, arg: Expr, callee: string): string {
    if (builtin !== IMPORT || this.opts.importTarget === undefined) {
      return callee;
    }
    if (arg.kind !== "path" || arg.anchor !== "relative") {
      return callee;
    }
    if (!arg.parts.every((p) => typeof p === "string")) {
      return callee;
    }
    const target = this.opts.importTarget(arg.parts.join(""));
    if (target === null) {
      return callee;
    }
    return `${callee} as nix.Imported<typeof import(${JSON.stringify(target)})>`;
  }

  // The builtin a call head denotes statically: a global like `map`, or
  // `builtins.map` on the unshadowed `builtins`.
  private builtinHead(head: Expr, scope: Scope): string | null {
    if (head.kind === "var") {
      if (scope.resolve(head.name).kind !== "global") {
        return null;
      }
      return this.globalBuiltin(head.name);
    }
    if (
      head.kind === "select" &&
      head.fallback === undefined &&
      head.subject.kind === "var" &&
      head.subject.name === "builtins" &&
      head.path.length === 1
    ) {
      if (scope.resolve("builtins").kind !== "global") {
        return null;
      }
      const a = head.path[0]!;
      if (a.kind === "static" && BUILTIN_ARITY.has(a.name)) {
        return a.name;
      }
    }
    return null;
  }

  // ---- operators ------------------------------------------------------------

  private binary(
    op: string,
    left: Expr,
    right: Expr,
    scope: Scope,
    depth: number,
  ): string {
    const a = (): string => this.operand(left, scope, depth);
    const b = (): string => this.operand(right, scope, depth);
    switch (op) {
      case "&&":
        return `(nix.asBool(${a()}) && nix.asBool(${b()}))`;
      case "||":
        return `(nix.asBool(${a()}) || nix.asBool(${b()}))`;
      case "->":
        return `(!nix.asBool(${a()}) || nix.asBool(${b()}))`;
      case "==":
        return `nix.eq(${a()}, ${b()})`;
      case "!=":
        return `!nix.eq(${a()}, ${b()})`;
      case "<":
        return `nix.lt(${a()}, ${b()})`;
      case ">":
        return `nix.gt(${a()}, ${b()})`;
      case "<=":
        return `nix.le(${a()}, ${b()})`;
      case ">=":
        return `nix.ge(${a()}, ${b()})`;
      case "//":
        return `nix.update(${a()}, ${b()})`;
      case "++":
        return `nix.concat(${a()}, ${b()})`;
      case "+":
        return `nix.add(${a()}, ${b()})`;
      case "-":
        return `nix.sub(${a()}, ${b()})`;
      case "*":
        return `nix.mul(${a()}, ${b()})`;
      case "/":
        return `nix.div(${a()}, ${b()})`;
      case "|>":
        return `nix.app(${b()}, ${this.lazy(left, scope, depth + 1)})`;
      case "<|":
        return `nix.app(${a()}, ${this.lazy(right, scope, depth + 1)})`;
      default:
        throw new Error(`internal: unknown operator ${op}`);
    }
  }

  // ---- layout ---------------------------------------------------------------

  // A bracketed list, on one line when short and one item per line
  // otherwise.
  private bracketed(
    open: string,
    items: string[],
    close: string,
    depth: number,
  ): string {
    const oneLine = `${open} ${items.join(", ")} ${close}`;
    if (
      oneLine.replace(ALL_MARKERS, "").length <= 80 &&
      !oneLine.includes("\n")
    ) {
      return open === "[" ? `[${items.join(", ")}]` : oneLine;
    }
    const pad = INDENT.repeat(depth + 1);
    const end = INDENT.repeat(depth);
    return `${open}\n${items.map((i) => pad + i + ",").join("\n")}\n${end}${close}`;
  }

  // An immediately invoked block returning its last statement.
  private block(stmts: string[], depth: number): string {
    const pad = INDENT.repeat(depth + 1);
    const end = INDENT.repeat(depth);
    return `(() => {\n${stmts.map((s) => pad + s).join("\n")}\n${end}})()`;
  }
}

// An arrow function whose body is an object literal needs parentheses, or
// the braces read as a block.
function arrowBody(expr: string): string {
  return expr.replace(LEADING_MARKER, "").startsWith("{") ? `(${expr})` : expr;
}

// A position stamp at the start of an emitted expression.
const LEADING_MARKER = /^\u0001[^\u0002]*\u0002/;
const ALL_MARKERS = /\u0001[^\u0002]*\u0002/g;

// `nix.builtins.map`, or `nix.builtins["foldl'"]` for names JavaScript
// cannot spell after a dot.
function builtinRef(name: string): string {
  return isIdentifierName(name)
    ? `nix.builtins.${name}`
    : `nix.builtins[${JSON.stringify(name)}]`;
}

// `__proto__` in an object literal sets the prototype even when quoted;
// only a computed key makes it an own property.
function propertyKey(name: string): string {
  if (name === "__proto__") {
    return '["__proto__"]';
  }
  if (isIdentifierName(name)) {
    return name;
  }
  return JSON.stringify(name);
}

function templateEscape(s: string): string {
  return s.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
}

// A float literal must read as a float: `1.0`, never `1`, and an exponent
// form (`1e+308`) is already one.
function floatLiteral(x: number): string {
  const text = String(x);
  if (Number.isInteger(x) && !/[eE]/.test(text)) {
    return `${text}.0`;
  }
  return text;
}
